// .local/build/S01.js
import { registerMvuSchema } from "https://cdn.jsdelivr.net/gh/StageDog/tavern_resource@dee97e8c3e24e1e75efe21141743e4b5c0af776e/dist/util/mvu_zod.js";
async function mount(__landlordScope) {
  const RoomSchema = __landlordScope.value("z").object({
    \u7C7B\u578B: __landlordScope.value("z").string().prefault("\u7A7A\u623F\u95F4"),
    \u540D\u79F0: __landlordScope.value("z").string().prefault("\u672A\u547D\u540D\u623F\u95F4"),
    \u697C\u5C42: __landlordScope.value("z").string().prefault("\u4E00\u697C"),
    \u4F4D\u7F6E: __landlordScope.value("z").string().prefault("1-2"),
    \u4F4F\u6237: __landlordScope.value("z").string().prefault("\u65E0"),
    \u63CF\u8FF0: __landlordScope.value("z").string().prefault("\u6682\u65E0\u63CF\u8FF0")
  }).prefault({}).refine((room) => {
    const occupants = room.\u4F4F\u6237.split("\u3001").map((s) => s.trim()).filter((s) => s && s !== "\u65E0" && s !== "<user>" && s !== "{{user}}");
    if (occupants.length > 0 && room.\u7C7B\u578B !== "\u5367\u5BA4" && room.\u7C7B\u578B !== "\u60A8\u7684\u623F\u95F4") return false;
    return true;
  }, { message: '\u6709\u79DF\u5BA2\u5C45\u4F4F\u7684\u623F\u95F4\u7C7B\u578B\u5FC5\u987B\u4E3A"\u5367\u5BA4"\uFF0C\u4E0D\u80FD\u5C06\u79DF\u5BA2\u5206\u914D\u5230\u975E\u5367\u5BA4\u623F\u95F4' });
  const Schema = __landlordScope.value("z").object({
    // 世界时间
    \u4E16\u754C: __landlordScope.value("z").object({
      \u5E74\u4EFD: __landlordScope.value("z").string().prefault("2024"),
      \u65E5\u671F: __landlordScope.value("z").string().prefault("1\u67081\u65E5"),
      \u661F\u671F: __landlordScope.value("z").string().prefault("\u661F\u671F\u4E00"),
      \u65F6\u95F4: __landlordScope.value("z").string().prefault("\u4E0A\u5348")
    }).prefault({}),
    // 公寓配置
    \u516C\u5BD3: __landlordScope.value("z").object({
      \u697C\u5C42\u5217\u8868: __landlordScope.value("z").array(__landlordScope.value("z").string()).prefault([]),
      \u623F\u95F4\u5217\u8868: __landlordScope.value("z").record(
        __landlordScope.value("z").string().describe("\u623F\u95F4\u540D"),
        RoomSchema
      ).prefault({})
    }).prefault({}),
    // 租客列表（动态键：租客姓名 -> 租客数据）
    // 只保留核心字段：年龄、外貌、职业、性格、状态、内心、关系
    \u79DF\u5BA2\u5217\u8868: __landlordScope.value("z").record(
      __landlordScope.value("z").string().describe("\u79DF\u5BA2\u59D3\u540D"),
      __landlordScope.value("z").object({
        \u5E74\u9F84: __landlordScope.value("z").coerce.number().prefault(20),
        \u5916\u8C8C: __landlordScope.value("z").string().prefault("\u5F85\u63CF\u8FF0"),
        \u804C\u4E1A: __landlordScope.value("z").string().prefault("\u65E0"),
        \u6027\u683C: __landlordScope.value("z").string().prefault("\u5F85\u63CF\u8FF0"),
        \u72B6\u6001: __landlordScope.value("z").string().prefault("\u6B63\u5E38"),
        \u5185\u5FC3: __landlordScope.value("z").string().prefault("\u5E73\u9759"),
        \u5173\u7CFB: __landlordScope.value("z").record(
          __landlordScope.value("z").string().describe("\u5BF9\u8C61\u540D"),
          __landlordScope.value("z").string().describe("\u5173\u7CFB\u63CF\u8FF0")
        ).prefault({})
      }).prefault({})
    ).prefault({})
  }).superRefine((data, ctx) => {
    const tenantNames = new Set(Object.keys(data.\u79DF\u5BA2\u5217\u8868 || {}));
    const rooms = data.\u516C\u5BD3?.\u623F\u95F4\u5217\u8868 || {};
    for (const [roomKey, room] of Object.entries(rooms)) {
      const occupant = room.\u4F4F\u6237;
      if (!occupant || occupant === "\u65E0") continue;
      if (room.\u7C7B\u578B === "\u60A8\u7684\u623F\u95F4") continue;
      const names = occupant.split("\u3001").map((s) => s.trim()).filter((s) => s && s !== "\u65E0" && s !== "<user>" && s !== "{{user}}");
      for (const name of names) {
        if (!tenantNames.has(name)) {
          ctx.addIssue({
            code: "custom",
            message: "\u623F\u95F4\u300C" + roomKey + "\u300D\u7684\u4F4F\u6237\u300C" + name + "\u300D\u4E0D\u5728\u79DF\u5BA2\u5217\u8868\u4E2D\uFF0C\u8BF7\u540C\u65F6\u6DFB\u52A0\u79DF\u5BA2\u6863\u6848",
            path: ["\u516C\u5BD3", "\u623F\u95F4\u5217\u8868", roomKey, "\u4F4F\u6237"]
          });
        }
      }
    }
    for (const tenantName of tenantNames) {
      let found = false;
      for (const room of Object.values(rooms)) {
        const names = (room.\u4F4F\u6237 || "").split("\u3001").map((s) => s.trim());
        if (names.includes(tenantName)) {
          found = true;
          break;
        }
      }
      if (!found) {
        ctx.addIssue({
          code: "custom",
          message: "\u79DF\u5BA2\u300C" + tenantName + "\u300D\u672A\u5206\u914D\u5230\u4EFB\u4F55\u623F\u95F4\uFF0C\u8BF7\u66F4\u65B0\u5BF9\u5E94\u5367\u5BA4\u7684\u4F4F\u6237\u5B57\u6BB5",
          path: ["\u79DF\u5BA2\u5217\u8868", tenantName]
        });
      }
    }
  });
  __landlordScope.value("$")(() => {
    __landlordScope.value("landlord").registerSchema(registerMvuSchema, Schema);
    __landlordScope.value("console").log("\u2705 \u623F\u4E1C\u6A21\u62DF\u5668\u53D8\u91CF\u7ED3\u6784\u5DF2\u6CE8\u518C");
  });
  await __landlordScope.flushReady();
}

// .local/build/S02.js
async function mount2(__landlordScope) {
  (function() {
    "use strict";
    __landlordScope.value("console").log("[FloatingMenuManager] \u811A\u672C\u5F00\u59CB\u52A0\u8F7D...");
    const parentDocument = __landlordScope.value("window").parent.document;
    const CONFIG = {
      MAIN_SIZE: 56,
      // 主球尺寸
      SUB_SIZE: 48,
      // 子球尺寸
      SUB_SPACING: 60,
      // 子球间距
      VIEWPORT_MARGIN: 8,
      // 保留触摸和阴影的边缘空间
      DRAG_THRESHOLD: 5,
      // 拖拽阈值（px）
      ANIMATION_DURATION: 300,
      // 动画时长（ms）
      Z_INDEX_MAIN: 1e4,
      // 主球层级
      Z_INDEX_SUB: 9999,
      // 子球层级
      STORAGE_KEY: "floatingMenuManager_state"
    };
    const ICONS = {
      // 三横线图标（收起状态）
      menu: `<svg width="20" height="20" viewBox="0 0 16 16" fill="currentColor">
            <path fill-rule="evenodd" d="M2.5 12a.5.5 0 0 1 .5-.5h10a.5.5 0 0 1 0 1H3a.5.5 0 0 1-.5-.5zm0-4a.5.5 0 0 1 .5-.5h10a.5.5 0 0 1 0 1H3a.5.5 0 0 1-.5-.5zm0-4a.5.5 0 0 1 .5-.5h10a.5.5 0 0 1 0 1H3a.5.5 0 0 1-.5-.5z"/>
        </svg>`,
      // 向下箭头图标（展开状态）
      chevronDown: `<svg width="20" height="20" viewBox="0 0 16 16" fill="currentColor">
            <path fill-rule="evenodd" d="M1.646 4.646a.5.5 0 0 1 .708 0L8 10.293l5.646-5.647a.5.5 0 0 1 .708.708l-6 6a.5.5 0 0 1-.708 0l-6-6a.5.5 0 0 1 0-.708z"/>
        </svg>`
    };
    const state = {
      isExpanded: false,
      // 展开状态
      isDragging: false,
      // 拖拽状态
      hasMoved: false,
      // 是否移动过
      buttons: [],
      // 注册的按钮配置
      cleanups: [],
      // 重新初始化时移除宿主页面上的监听
      elements: {
        // DOM元素引用
        main: null,
        // 主悬浮球
        subContainer: null,
        // 子球容器
        subs: []
        // 子球数组
      },
      dragData: {
        // 拖拽数据
        startX: 0,
        startY: 0,
        initialBottom: 0,
        initialRight: 0
      },
      position: {
        // 位置（使用top/left定位）
        top: 100,
        left: 20
      }
    };
    function injectStyles() {
      if (parentDocument.getElementById("floating-menu-manager-styles")) return;
      const styles = `
<style id="floating-menu-manager-styles">
/* \u4E3B\u60AC\u6D6E\u7403 */
.fmm-main-fab {
    position: fixed;
    width: ${CONFIG.MAIN_SIZE}px;
    height: ${CONFIG.MAIN_SIZE}px;
    border-radius: 50%;
    background: linear-gradient(135deg, #4B5563 0%, #374151 100%);
    box-shadow: 0 4px 20px rgba(0,0,0,0.3);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    z-index: ${CONFIG.Z_INDEX_MAIN};
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    user-select: none;
    -webkit-user-select: none;
    color: white;
}

.fmm-main-fab:hover {
    transform: scale(1.1);
    box-shadow: 0 6px 25px rgba(0,0,0,0.4);
}

.fmm-main-fab:active {
    transform: scale(0.95);
}

.fmm-main-fab.dragging {
    cursor: move;
    transform: scale(1.05);
}

.fmm-main-fab .icon {
    transition: transform 0.3s ease;
    display: flex;
    align-items: center;
    justify-content: center;
}

.fmm-main-fab.expanded .icon {
    transform: rotate(180deg);
}

/* \u5B50\u7403\u5BB9\u5668 */
.fmm-sub-container {
    position: fixed;
    z-index: ${CONFIG.Z_INDEX_SUB};
    pointer-events: none;
}
.fmm-sub-container.scrollable.expanded {
    pointer-events: auto;
    overflow: auto;
    overscroll-behavior: contain;
    background: rgba(31, 41, 55, 0.9);
    border-radius: 12px;
}

/* \u5B50\u60AC\u6D6E\u7403 */
.fmm-sub-fab {
    position: absolute;
    width: ${CONFIG.SUB_SIZE}px;
    height: ${CONFIG.SUB_SIZE}px;
    border-radius: 50%;
    box-shadow: 0 3px 15px rgba(0,0,0,0.25);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: transform 0.2s ease, opacity 0.2s ease, box-shadow 0.2s ease;
    user-select: none;
    -webkit-user-select: none;
    pointer-events: none;
    opacity: 0;
    visibility: hidden;
    transform: scale(0.8);
}
.fmm-sub-container.expanded .fmm-sub-fab {
    pointer-events: auto;
    opacity: 1;
    visibility: visible;
    transform: scale(1);
}
.fmm-sub-container.expanded .fmm-sub-fab:hover {
    transform: scale(1.1);
    box-shadow: 0 4px 20px rgba(0,0,0,0.35);
}

.fmm-sub-container.expanded .fmm-sub-fab:active {
    transform: scale(0.9);
}

</style>
        `;
      parentDocument.head.insertAdjacentHTML("beforeend", styles);
    }
    function createMainFab() {
      const fab = parentDocument.createElement("div");
      fab.className = "fmm-main-fab";
      fab.setAttribute("role", "button");
      fab.setAttribute("aria-label", "\u623F\u4E1C\u6A21\u62DF\u5668\u529F\u80FD\u83DC\u5355");
      fab.setAttribute("aria-expanded", "false");
      fab.tabIndex = 0;
      fab.innerHTML = `<div class="icon">${ICONS.menu}</div>`;
      fab.style.top = state.position.top + "px";
      fab.style.left = state.position.left + "px";
      parentDocument.body.appendChild(fab);
      state.elements.main = fab;
      bindMainFabEvents(fab);
      return fab;
    }
    function createSubContainer() {
      const container = parentDocument.createElement("div");
      container.className = "fmm-sub-container";
      parentDocument.body.appendChild(container);
      state.elements.subContainer = container;
      return container;
    }
    function viewportBounds() {
      const viewport = __landlordScope.value("window").parent.visualViewport;
      const left = viewport ? viewport.offsetLeft : 0;
      const top = viewport ? viewport.offsetTop : 0;
      const width = viewport ? viewport.width : __landlordScope.value("window").parent.innerWidth;
      const height = viewport ? viewport.height : __landlordScope.value("window").parent.innerHeight;
      const margin = CONFIG.VIEWPORT_MARGIN;
      return {
        left: left + margin,
        top: top + margin,
        right: left + width - margin,
        bottom: top + height - margin
      };
    }
    function clamp(value, min, max) {
      return Math.max(min, Math.min(value, Math.max(min, max)));
    }
    function updateSubContainerPosition() {
      if (!state.elements.main || !state.elements.subContainer) return;
      const container = state.elements.subContainer;
      const count = state.elements.subs.length;
      if (!count) return;
      const bounds = viewportBounds();
      const size = CONFIG.SUB_SIZE, spacing = CONFIG.SUB_SPACING, gap = spacing - size;
      const { top, left } = state.position;
      const mainBottom = top + CONFIG.MAIN_SIZE, mainRight = left + CONFIG.MAIN_SIZE;
      const length = count * spacing - gap;
      const centerX = clamp(left + (CONFIG.MAIN_SIZE - size) / 2, bounds.left, bounds.right - size);
      const centerY = clamp(top + (CONFIG.MAIN_SIZE - size) / 2, bounds.top, bounds.bottom - size);
      let positions, scrollable = false, region;
      if (top - gap - bounds.top >= length) {
        positions = state.elements.subs.map((_, i) => ({ left: centerX, top: top - gap - size - i * spacing }));
      } else if (bounds.bottom - mainBottom - gap >= length) {
        positions = state.elements.subs.map((_, i) => ({ left: centerX, top: mainBottom + gap + i * spacing }));
      } else if (bounds.right - mainRight - gap >= length) {
        positions = state.elements.subs.map((_, i) => ({ left: mainRight + gap + i * spacing, top: centerY }));
      } else if (left - gap - bounds.left >= length) {
        positions = state.elements.subs.map((_, i) => ({ left: left - gap - size - i * spacing, top: centerY }));
      } else {
        const regions = [
          { left: bounds.left, top: bounds.top, right: bounds.right, bottom: top - gap },
          { left: bounds.left, top: mainBottom + gap, right: bounds.right, bottom: bounds.bottom },
          { left: bounds.left, top: bounds.top, right: left - gap, bottom: bounds.bottom },
          { left: mainRight + gap, top: bounds.top, right: bounds.right, bottom: bounds.bottom }
        ].map((area) => ({
          ...area,
          columns: Math.max(0, Math.floor((area.right - area.left + gap) / spacing)),
          rows: Math.max(0, Math.floor((area.bottom - area.top + gap) / spacing))
        })).sort((a, b) => b.columns * b.rows - a.columns * a.rows);
        region = regions[0];
        if (!region.columns || !region.rows) {
          region = { ...bounds, columns: Math.max(1, Math.floor((bounds.right - bounds.left + gap) / spacing)), rows: 1 };
        }
        scrollable = region.columns * region.rows < count;
        const columns = Math.min(count, region.columns);
        positions = state.elements.subs.map((_, i) => ({
          left: region.left + i % columns * spacing,
          top: region.top + Math.floor(i / columns) * spacing
        }));
      }
      const originLeft = Math.min(...positions.map((position) => position.left));
      const originTop = Math.min(...positions.map((position) => position.top));
      container.style.left = originLeft + "px";
      container.style.top = originTop + "px";
      container.style.width = Math.max(...positions.map((position) => position.left)) + size - originLeft + "px";
      container.style.height = (scrollable ? region.bottom - originTop : Math.max(...positions.map((position) => position.top)) + size - originTop) + "px";
      container.classList.toggle("scrollable", scrollable);
      container.classList.toggle("expanded", state.isExpanded);
      state.elements.subs.forEach((fab, index) => {
        fab.style.left = positions[index].left - originLeft + "px";
        fab.style.top = positions[index].top - originTop + "px";
        fab.tabIndex = state.isExpanded ? 0 : -1;
      });
    }
    function createSubFab(config, index) {
      const fab = parentDocument.createElement("div");
      fab.className = "fmm-sub-fab";
      fab.setAttribute("role", "button");
      fab.setAttribute("aria-label", config.label || config.id);
      fab.title = config.label || config.id;
      fab.tabIndex = state.isExpanded ? 0 : -1;
      fab.style.background = config.color || "linear-gradient(135deg, #667eea 0%, #764ba2 100%)";
      if (typeof config.icon === "string") {
        fab.innerHTML = config.icon;
      } else {
        fab.textContent = config.icon || "\u25CF";
      }
      fab.addEventListener("click", function(e) {
        e.stopPropagation();
        if (config.onClick && typeof config.onClick === "function") {
          config.onClick();
        }
      });
      fab.addEventListener("keydown", function(e) {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          fab.click();
        }
      });
      state.elements.subContainer.appendChild(fab);
      state.elements.subs.push(fab);
      return fab;
    }
    function renderSubFabs() {
      state.elements.subs.forEach((fab) => fab.remove());
      state.elements.subs = [];
      state.buttons.forEach((config, index) => {
        createSubFab(config, index);
      });
      updateSubContainerPosition();
    }
    function expand() {
      if (state.isExpanded) return;
      state.isExpanded = true;
      const icon = state.elements.main.querySelector(".icon");
      icon.innerHTML = ICONS.chevronDown;
      state.elements.main.classList.add("expanded");
      state.elements.main.setAttribute("aria-expanded", "true");
      updateSubContainerPosition();
    }
    function collapse() {
      if (!state.isExpanded) return;
      state.isExpanded = false;
      const icon = state.elements.main.querySelector(".icon");
      icon.innerHTML = ICONS.menu;
      state.elements.main.classList.remove("expanded");
      state.elements.main.setAttribute("aria-expanded", "false");
      state.elements.subContainer.classList.remove("expanded");
      state.elements.subs.forEach((fab) => {
        fab.tabIndex = -1;
      });
    }
    function toggle() {
      if (state.isExpanded) {
        collapse();
      } else {
        expand();
      }
    }
    function bindMainFabEvents(fab) {
      let rafId = null;
      let pendingMove = null;
      function applyMove() {
        if (!pendingMove) return;
        const bounds = viewportBounds();
        state.position.left = clamp(pendingMove.left, bounds.left, bounds.right - CONFIG.MAIN_SIZE);
        state.position.top = clamp(pendingMove.top, bounds.top, bounds.bottom - CONFIG.MAIN_SIZE);
        pendingMove = null;
        fab.style.left = state.position.left + "px";
        fab.style.top = state.position.top + "px";
        updateSubContainerPosition();
        rafId = null;
      }
      function handleStart(e) {
        const touch = e.touches ? e.touches[0] : e;
        state.isDragging = true;
        state.hasMoved = false;
        state.dragData.startX = touch.clientX;
        state.dragData.startY = touch.clientY;
        state.dragData.initialTop = state.position.top;
        state.dragData.initialLeft = state.position.left;
        fab.classList.add("dragging");
        e.preventDefault();
      }
      function handleMove(e) {
        if (!state.isDragging) return;
        const touch = e.touches ? e.touches[0] : e;
        const deltaX = touch.clientX - state.dragData.startX;
        const deltaY = touch.clientY - state.dragData.startY;
        if (Math.abs(deltaX) > CONFIG.DRAG_THRESHOLD || Math.abs(deltaY) > CONFIG.DRAG_THRESHOLD) {
          state.hasMoved = true;
        }
        if (rafId) __landlordScope.value("cancelAnimationFrame")(rafId);
        pendingMove = { left: state.dragData.initialLeft + deltaX, top: state.dragData.initialTop + deltaY };
        rafId = __landlordScope.value("requestAnimationFrame")(applyMove);
        e.preventDefault();
      }
      function handleEnd(e) {
        if (!state.isDragging) return;
        if (rafId) __landlordScope.value("cancelAnimationFrame")(rafId);
        applyMove();
        state.isDragging = false;
        fab.classList.remove("dragging");
        savePosition();
        if (!state.hasMoved) {
          toggle();
        }
        state.hasMoved = false;
        e.preventDefault();
      }
      listen(fab, "mousedown", handleStart);
      listen(parentDocument, "mousemove", handleMove);
      listen(parentDocument, "mouseup", handleEnd);
      listen(fab, "touchstart", handleStart, { passive: false });
      listen(parentDocument, "touchmove", handleMove, { passive: false });
      listen(parentDocument, "touchend", handleEnd, { passive: false });
      listen(parentDocument, "touchcancel", handleEnd, { passive: false });
      listen(fab, "keydown", function(e) {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          toggle();
        }
      });
      listen(parentDocument, "keydown", function(e) {
        if (e.key === "Escape" && state.isExpanded) collapse();
      });
      state.cleanups.push(() => {
        if (rafId) __landlordScope.value("cancelAnimationFrame")(rafId);
      });
    }
    function listen(target, type, callback, options) {
      target.addEventListener(type, callback, options);
      state.cleanups.push(() => target.removeEventListener(type, callback, options));
    }
    function savePosition() {
      try {
        const data = {
          top: state.position.top,
          left: state.position.left,
          isExpanded: state.isExpanded
        };
        __landlordScope.value("localStorage").setItem(CONFIG.STORAGE_KEY, JSON.stringify(data));
      } catch (e) {
        __landlordScope.value("console").error("[FloatingMenuManager] \u4FDD\u5B58\u4F4D\u7F6E\u5931\u8D25:", e);
      }
    }
    function loadPosition() {
      try {
        const saved = __landlordScope.value("localStorage").getItem(CONFIG.STORAGE_KEY);
        if (saved) {
          const data = JSON.parse(saved);
          state.position.top = Number.isFinite(data.top) ? data.top : 100;
          state.position.left = Number.isFinite(data.left) ? data.left : 20;
        }
      } catch (e) {
        __landlordScope.value("console").error("[FloatingMenuManager] \u52A0\u8F7D\u4F4D\u7F6E\u5931\u8D25:", e);
      }
    }
    function adjustPositionToViewport() {
      if (!state.elements.main) return;
      const bounds = viewportBounds();
      const left = clamp(state.position.left, bounds.left, bounds.right - CONFIG.MAIN_SIZE);
      const top = clamp(state.position.top, bounds.top, bounds.bottom - CONFIG.MAIN_SIZE);
      const adjusted = left !== state.position.left || top !== state.position.top;
      state.position.left = left;
      state.position.top = top;
      if (adjusted) {
        state.elements.main.style.left = state.position.left + "px";
        state.elements.main.style.top = state.position.top + "px";
        savePosition();
      }
      updateSubContainerPosition();
    }
    function bindWindowResize() {
      let resizeTimer = null;
      function scheduleResize() {
        if (resizeTimer) __landlordScope.value("clearTimeout")(resizeTimer);
        resizeTimer = __landlordScope.value("setTimeout")(function() {
          adjustPositionToViewport();
          resizeTimer = null;
        }, 100);
      }
      listen(__landlordScope.value("window").parent, "resize", scheduleResize);
      if (__landlordScope.value("window").parent.visualViewport) {
        listen(__landlordScope.value("window").parent.visualViewport, "resize", scheduleResize);
        listen(__landlordScope.value("window").parent.visualViewport, "scroll", scheduleResize);
      }
      state.cleanups.push(() => {
        if (resizeTimer) __landlordScope.value("clearTimeout")(resizeTimer);
      });
    }
    const FloatingMenuManager = {
      /**
       * 注册子按钮
       * @param {Object} config - 按钮配置
       * @param {string} config.id - 按钮唯一ID
       * @param {string|HTMLElement} config.icon - 图标（可以是emoji、SVG字符串或HTML）
       * @param {string} config.label - 按钮标签（用于调试）
       * @param {Function} config.onClick - 点击回调函数
       * @param {string} config.color - 背景渐变色
       * @param {number} config.order - 排序顺序（可选，默认按注册顺序）
       */
      registerButton: function(config) {
        if (!config || !config.id) {
          __landlordScope.value("console").error("[FloatingMenuManager] \u6CE8\u518C\u5931\u8D25\uFF1A\u7F3A\u5C11\u5FC5\u8981\u53C2\u6570 id");
          return false;
        }
        const existingIndex = state.buttons.findIndex((btn) => btn.id === config.id);
        if (existingIndex !== -1) {
          __landlordScope.value("console").warn("[FloatingMenuManager] \u6309\u94AE\u5DF2\u5B58\u5728\uFF0C\u5C06\u66F4\u65B0\u914D\u7F6E:", config.id);
          state.buttons[existingIndex] = config;
        } else {
          state.buttons.push(config);
        }
        state.buttons.sort((a, b) => (a.order || 99) - (b.order || 99));
        if (state.elements.subContainer) {
          renderSubFabs();
        }
        __landlordScope.value("console").log("[FloatingMenuManager] \u6CE8\u518C\u6210\u529F:", config.id);
        return true;
      },
      /**
       * 取消注册按钮
       * @param {string} id - 按钮ID
       */
      unregisterButton: function(id) {
        const index = state.buttons.findIndex((btn) => btn.id === id);
        if (index !== -1) {
          state.buttons.splice(index, 1);
          if (state.elements.subContainer) {
            renderSubFabs();
          }
          __landlordScope.value("console").log("[FloatingMenuManager] \u53D6\u6D88\u6CE8\u518C:", id);
          return true;
        }
        return false;
      },
      /**
       * 展开菜单
       */
      expand: function() {
        expand();
      },
      /**
       * 收起菜单
       */
      collapse: function() {
        collapse();
      },
      /**
       * 切换展开/收起
       */
      toggle: function() {
        toggle();
      },
      /**
       * 初始化管理器
       */
      init: function() {
        __landlordScope.value("console").log("[FloatingMenuManager] \u521D\u59CB\u5316...");
        this.destroy();
        loadPosition();
        injectStyles();
        createMainFab();
        createSubContainer();
        var pending = __landlordScope.value("window").parent._fmmPendingRegistrations;
        if (pending && pending.length) {
          pending.forEach(function(config) {
            FloatingMenuManager.registerButton(config);
          });
          __landlordScope.value("window").parent._fmmPendingRegistrations = [];
          __landlordScope.value("console").log("[FloatingMenuManager] \u5904\u7406\u4E86 " + pending.length + " \u4E2A\u5F85\u6CE8\u518C\u6309\u94AE");
        }
        renderSubFabs();
        adjustPositionToViewport();
        bindWindowResize();
        __landlordScope.value("console").log("[FloatingMenuManager] \u521D\u59CB\u5316\u5B8C\u6210");
      },
      /**
       * 销毁管理器
       */
      destroy: function() {
        state.cleanups.splice(0).forEach((cleanup) => cleanup());
        if (state.elements.main) {
          state.elements.main.remove();
          state.elements.main = null;
        }
        if (state.elements.subContainer) {
          state.elements.subContainer.remove();
          state.elements.subContainer = null;
        }
        parentDocument.querySelectorAll(".fmm-main-fab").forEach(function(el) {
          el.remove();
        });
        parentDocument.querySelectorAll(".fmm-sub-container").forEach(function(el) {
          el.remove();
        });
        const styles = parentDocument.getElementById("floating-menu-manager-styles");
        if (styles) styles.remove();
        state.elements.subs = [];
        state.buttons = [];
        state.isExpanded = false;
        state.isDragging = false;
        state.hasMoved = false;
        __landlordScope.value("console").log("[FloatingMenuManager] \u5DF2\u9500\u6BC1");
      },
      /**
       * 获取当前状态
       */
      getState: function() {
        return {
          isExpanded: state.isExpanded,
          buttonCount: state.buttons.length,
          position: { ...state.position }
        };
      },
      /**
       * 获取已注册的按钮列表
       */
      getButtons: function() {
        return state.buttons.map((btn) => ({
          id: btn.id,
          label: btn.label,
          order: btn.order
        }));
      }
    };
    if (typeof __landlordScope.value("window") !== "undefined") {
      __landlordScope.value("window").parent.FloatingMenuManager = FloatingMenuManager;
      __landlordScope.value("console").log("[FloatingMenuManager] \u5DF2\u52A0\u8F7D\u5230 window.parent.FloatingMenuManager");
    }
    if (parentDocument.readyState === "loading") {
      parentDocument.addEventListener("DOMContentLoaded", function() {
        FloatingMenuManager.init();
      });
    } else {
      FloatingMenuManager.init();
    }
    __landlordScope.value("$")(__landlordScope.value("window")).on("pagehide", function() {
      __landlordScope.value("console").log("[FloatingMenuManager] \u811A\u672C\u5378\u8F7D\uFF0C\u6267\u884C\u6E05\u7406...");
      FloatingMenuManager.destroy();
    });
  })();
  await __landlordScope.flushReady();
}

