    __landlordScope.value("console").log("[\u79DF\u5BA2\u5206\u6790] \u4E0A\u6B21\u5206\u6790\u697C\u5C42:", TenantAnalyzer.lastAnalyzedFloor, "\u4E0A\u6B21\u5206\u6790\u65F6\u95F4:", TenantAnalyzer.lastAnalysisTime);
