      // 即时同步（带防抖）
      instantSync: function(conversationId) {
        if (!SYNC_CONFIG.instantSyncEnabled) return Promise.resolve(false);
        return this.syncToChatLore(conversationId);
      },
      // ==================== 删除同步 ====================
