    async function sendMessage() {
      const doc = currentIframeDoc || __landlordScope.value("document");
      const input = doc.getElementById("chat-input");
      const sendBtn = doc.getElementById("btn-send");
      const content = input.value.trim();
      if (!content || !AppState.currentConversation) return;
      const conversation = AppState.currentConversation;
      const ChatCore = __landlordScope.value("window").parent.ChatCore;
      const ChatDB = __landlordScope.value("window").parent.ChatDB;
      input.disabled = true;
      sendBtn.disabled = true;
      sendBtn.textContent = "...";
      sendBtn.classList.add("loading");
      try {
        await ChatCore.sendUserMessage(conversation.id, content);
        input.value = "";
        await renderMessages();
        const typingEl = doc.getElementById("typing-indicator");
        if (typingEl) typingEl.classList.add("show");
        const isGroup = conversation.type === "group";
        if (isGroup) {
          await ChatCore.generateGroupReply(conversation.id, content);
        } else {
          await ChatCore.generatePrivateReply(conversation.id, content);
        }
        if (__landlordScope.value("window").parent.ChatSync) {
          await __landlordScope.value("window").parent.ChatSync.instantSync(conversation.id);
        }
        await renderMessages();
      } catch (e) {
        __landlordScope.value("console").error("[ChatApp] \u53D1\u9001\u6D88\u606F\u5931\u8D25:", e);
        if (e.name !== "AbortError") __landlordScope.value("alert")("\u53D1\u9001\u5931\u8D25: " + e.message);
      } finally {
        input.disabled = false;
        sendBtn.disabled = false;
        sendBtn.textContent = "\u53D1\u9001";
        sendBtn.classList.remove("loading");
        const typingEl = doc.getElementById("typing-indicator");
        if (typingEl) typingEl.classList.remove("show");
        input.focus();
      }
    }
    async function loadStickersFromWorkshop() {
      return new Promise((resolve) => {
        try {
          const request = __landlordScope.value("indexedDB").open("WorkshopStickersDB");
          request.onerror = () => {
            resolve([]);
          };
          request.onsuccess = (event) => {
            const db = event.target.result;
            if (!db.objectStoreNames.contains("stickers")) {
              db.close();
              resolve([]);
              return;
            }
            const tx = db.transaction("stickers", "readonly");
            const store = tx.objectStore("stickers");
            const all = store.getAll();
            all.onsuccess = () => {
              db.close();
              resolve(all.result || []);
            };
            all.onerror = () => {
              db.close();
              resolve([]);
            };
          };
        } catch (e) {
          __landlordScope.value("console").warn("[ChatApp] \u8BFB\u53D6\u8868\u60C5\u5305\u5931\u8D25:", e);
          resolve([]);
        }
      });
    }
    let cachedStickers = null;
    let stickerCacheTime = 0;
    const STICKER_CACHE_TTL = 3e4;
    async function getStickers() {
      const now = Date.now();
      if (cachedStickers && now - stickerCacheTime < STICKER_CACHE_TTL) {
        return cachedStickers;
      }
      cachedStickers = await loadStickersFromWorkshop();
      stickerCacheTime = now;
      return cachedStickers;
    }
