  async function wsCompressImage(file) {
    if (file.type === "image/gif") {
      return new Promise((resolve) => {
        const reader = new (__landlordScope.value("FileReader"))();
        reader.onload = () => resolve(reader.result);
        reader.readAsDataURL(file);
      });
    }
    return new Promise((resolve) => {
      const reader = new (__landlordScope.value("FileReader"))();
      reader.onload = (e) => {
        const img = new (__landlordScope.value("Image"))();
        img.onload = () => {
          const canvas = __landlordScope.value("document").createElement("canvas");
          const scale = Math.min(256 / img.width, 256 / img.height, 1);
          canvas.width = Math.round(img.width * scale);
          canvas.height = Math.round(img.height * scale);
          canvas.getContext("2d").drawImage(img, 0, 0, canvas.width, canvas.height);
          canvas.toBlob((blob) => {
            const r2 = new (__landlordScope.value("FileReader"))();
            r2.onload = () => resolve(r2.result);
            r2.readAsDataURL(blob);
          }, "image/webp", 0.8);
        };
        img.src = e.target.result;
      };
      reader.readAsDataURL(file);
    });
  }
