      var room = layout.rooms[name];
      if (room.\u697C\u5C42 !== floor) continue;
      if (room.\u4F4D\u7F6E && room.\u4F4D\u7F6E.startsWith && room.\u4F4D\u7F6E.startsWith("outdoor")) continue;
      var parts = (room.\u4F4D\u7F6E || "").split("-").map(Number);
