      html += '<textarea class="ws-input" id="ws-upload-greeting" placeholder="\u5F00\u573A\u767D\u6545\u4E8B\u6587\u672C\uFF08\u4E0D\u542B\u53D8\u91CF\u66F4\u65B0\u90E8\u5206\uFF09" rows="6" style="padding:8px 10px;resize:vertical;min-height:90px;"></textarea>';
