      html += '<div><label style="font-size:10px;color:#9CA3AF;">\u65E5\u671F</label><input class="ws-input" id="ws-uv-date" placeholder="10\u670821\u65E5" style="padding:4px 8px;font-size:11px;"></div>';
      html += '<div><label style="font-size:10px;color:#9CA3AF;">\u661F\u671F</label><select class="ws-input" id="ws-uv-weekday" style="padding:4px 8px;font-size:11px;"><option value="">\u4E0D\u8BBE\u7F6E</option><option>\u661F\u671F\u4E00</option><option>\u661F\u671F\u4E8C</option><option>\u661F\u671F\u4E09</option><option>\u661F\u671F\u56DB</option><option>\u661F\u671F\u4E94</option><option>\u661F\u671F\u516D</option><option>\u661F\u671F\u65E5</option></select></div>';
