          if (names.length === 0) return AptSystem.showNotification("\u5F53\u524D\u6CA1\u6709\u5165\u4F4F\u79DF\u5BA2\uFF01", "warning");
          AptSystem.showNotification("\u5206\u6790\u6307\u4EE4\u5DF2\u4E0B\u8FBE\uFF0CAI\u6B63\u5728\u9010\u4E2A\u5206\u6790...", "success");
